```js
function findNestedValue(obj, key) {
  const keys = key.split('.');
  let val = obj;

  for (let I = 0; I < keys.length; i++) {
    if (!val[keys[i]]) {
      return undefined;
    }

    val = val[keys[i]];
  }

  return val;
}

const myObject = {
  person: {
    name: 'John Doe',
    age: 30,
    address: {
