      city: 'Anytown',
      state: 'CA'
    }
  }
};

// Example usage:
console.log(findNestedValue(myObject, 'person.address.city')); // Output: "Anytown"
```

Inside the `findNestedValue` function, we first split the input key into an array of keys separated by dots. Then, we start iterating over these keys and checking whether each key exists in the current object. If any key is missing, we immediately return `undefined`. Otherwise, we update the `val` variable with the value of the current key.

At the end, we simply return the final `val` value. Note that this function does not modify the original object - it only returns values based on the provided key.

