```java
public class Main {
    public static void main(String[] args) {
        Product[] products = {
            new Product("Headphone", 50),
            new Product("Headphone", 50),
            new Product("Headphone", 50),
            new Product("Headphone", 50),
            new Product("Microphone", 100),
            new Product("Microphone", 100),
            new Product("Speaker", 150),
            new Product("Speaker", 150),
            new Product("Speaker", 150)
        };

        int totalExpenses = 0;

        // Loop through all products and add their prices to total expenses
